-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        vantora_record_id,
        vantora_fund_id,
        fund_name,
        fund_family_name,
        vehicle_type,
        gp_source_id,
        gp_name,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        committed_capital_usd,
        currency,
        domicile,
        fund_status,
        as_of_date,
        violation_00,
        violation_01
    from {{ ref("investment__vantora_fund__checked") }}
),
violations as (
    select
        'vantora_record_id_not_null' as rule_name,
        vantora_record_id,
        vantora_fund_id,
        fund_name,
        fund_family_name,
        vehicle_type,
        gp_source_id,
        gp_name,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        committed_capital_usd,
        currency,
        domicile,
        fund_status,
        as_of_date
    from quarantined
    where violation_00

    union all

    select
        'fund_name_not_null' as rule_name,
        vantora_record_id,
        vantora_fund_id,
        fund_name,
        fund_family_name,
        vehicle_type,
        gp_source_id,
        gp_name,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        committed_capital_usd,
        currency,
        domicile,
        fund_status,
        as_of_date
    from quarantined
    where violation_01
)

select
    rule_name,
    vantora_record_id,
    vantora_fund_id,
    fund_name,
    fund_family_name,
    vehicle_type,
    gp_source_id,
    gp_name,
    fund_lei,
    shared_external_id,
    asset_class,
    strategy,
    vintage_year,
    committed_capital_usd,
    currency,
    domicile,
    fund_status,
    as_of_date
from violations
